/** @param {{des: object}} api */
export default function bigrm_5({ des, selection, percent }) {
    des.level_init({ style: 'solidfill', fg: ' ' });
    des.level_flags('mazelevel', 'noflip');

    des.map(`                            ------------------                            
                    ---------................---------                    
              -------................................-------              
         ------............................................------         
      ----......................................................----      
    ---............................................................---    
  ---................................................................---  
---....................................................................---
|........................................................................|
|........................................................................|
|........................................................................|
---....................................................................---
  ---................................................................---  
    ---............................................................---    
      ----......................................................----      
         ------............................................------         
              -------................................-------              
                    ---------................---------                    
                            ------------------                            
`);

    if (percent(25)) {
        const sel = selection.grow(selection.percentage(selection.match('.'), 2));
        des.replace_terrain({ selection: sel, fromterrain: '.', toterrain: percent(50) && 'I' || 'C' });
    }

    des.region(selection.area(0, 0, 72, 18), 'lit');

    des.stair('up');
    des.stair('down');

    des.non_diggable();

    for (let i = 1; i <= 15; i++) {
        des.object();
    }

    for (let i = 1; i <= 6; i++) {
        des.trap();
    }

    for (let i = 1; i <= 28; i++) {
        des.monster();
    }
}
